{
	// 红包类型 必填
	// default 普通
	// password 口令
	"type": "default",
	// 领取类型 必填
	// average 均分模式 红包总金额 / 可领人数
	// random 随机模式 每人至少可以领取1
	"receive": "average",
	// 红包总金额 1 - 60000 萝卜 必填
	"carrot": 2,
	// 可领人数 1 - 10000 人 必填
	"number": 2,
	// 寄语 50子内 必填
	"blessing": "新年快乐",
	// 字符串 区分大小写 1-50字符内 口令或专属时必填
	"text": null,
	// 文件访问url 图片类型建议小于1m
	// "file_url": "https://image.tmdb.org/t/p/w500/hew9LSQW4wk63aN1Z7cEBTISL9B.jpg",
	// 文件类型 如果存在 file_id 或 file_url 则必填 决定了红包的类型 支持 image audio
	// "file_type": "image",
	// 独占模式 存在file_url并且为true时bot只会显示文件内容 默认为 false
	"is_exclusive": true,
	// 过期时间 60秒 - 48小时 默认为24小时 单位秒
	"seconds": 120
}

{
	// 红包类型 必填
	// default 普通
	// password 口令
	"type": "password",
	// 领取类型 必填
	// average 均分模式 红包总金额 / 可领人数
	// random 随机模式 每人至少可以领取1
	"receive": "average",
	// 红包总金额 1 - 60000 萝卜 必填
	"carrot": 2,
	// 可领人数 1 - 10000 人 必填
	"number": 2,
	// 寄语 50子内 必填
	"blessing": "新年快乐",
	// 字符串 区分大小写 1-50字符内 口令或专属时必填
	"text": null,
	// 文件访问url 图片类型建议小于1m
	"file_url": "https://image.tmdb.org/t/p/w500/hew9LSQW4wk63aN1Z7cEBTISL9B.jpg",
	// 文件类型 如果存在 file_id 或 file_url 则必填 决定了红包的类型 支持 image audio
	"file_type": "image",
	// 独占模式 存在file_url并且为true时bot只会显示文件内容 默认为 false
	"is_exclusive": true
}
